// AnalyticsDashboard.tsx
import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';

const ANALYTICS_STALE_TIME = 5 * 60 * 1000; // 5 minutes
const ANALYTICS_CACHE_TIME = 10 * 60 * 1000; // 10 minutes

const fetchAnalytics = async () => {
  const res = await fetch('/api/analytics', {
    headers: { 'Accept': 'application/json' },
    signal: AbortSignal.timeout(5000)
  });
  if (!res.ok) throw new Error(`API error: ${res.status}`);
  return res.json();
};

const AnalyticsDashboard = () => {
  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ['analytics'],
    queryFn: fetchAnalytics,
    staleTime: ANALYTICS_STALE_TIME,
    gcTime: ANALYTICS_CACHE_TIME,
    retry: 2
  });

  if (isLoading) return <LoadingState />;
  if (error) return <ErrorState error={error as Error} onRetry={() => refetch()} />;

  const { dauTrend, signupRate, churnRate, featureUsage } = data;

  return (
    <div style={{ padding: '24px', maxWidth: '1400px', margin: '0 auto' }}>
      <h1 style={{ marginBottom: '32px', fontSize: '28px', fontWeight: '600' }}>Analytics</h1>

      {/* Metric cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px', marginBottom: '32px' }}>
        <MetricCard title="Signup Rate" value={`${signupRate}%`} change="+2.3%" />
        <MetricCard title="Churn Rate" value={`${churnRate}%`} change="-0.8%" />
        <MetricCard title="DAU" value="12.5K" change="+450" />
      </div>

      {/* Charts */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', gap: '24px' }}>
        <ChartContainer title="Daily Active Users (30 days)">
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={dauTrend}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Line type="monotone" dataKey="dau" stroke="#1976d2" strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </ChartContainer>

        <ChartContainer title="Feature Usage">
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={featureUsage}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="feature" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="usage" fill="#4caf50" />
            </BarChart>
          </ResponsiveContainer>
        </ChartContainer>
      </div>
    </div>
  );
};

const LoadingState = () => (
  <div style={{ padding: '48px', textAlign: 'center', color: '#999' }}>Loading analytics...</div>
);

const ErrorState = ({ error, onRetry }: { error: Error; onRetry: () => void }) => (
  <div style={{ padding: '24px', backgroundColor: '#ffebee', color: '#c62828', borderRadius: '8px' }}>
    <p>Failed to load analytics: {error.message}</p>
    <button onClick={onRetry} style={{ marginTop: '12px', padding: '8px 16px', backgroundColor: '#c62828', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
      Retry
    </button>
  </div>
);

const MetricCard = ({ title, value, change }: { title: string; value: string; change: string }) => (
  <div style={{ padding: '16px', backgroundColor: '#f5f5f5', borderRadius: '8px', border: '1px solid #e0e0e0' }}>
    <div style={{ fontSize: '12px', color: '#999', marginBottom: '8px' }}>{title}</div>
    <div style={{ fontSize: '24px', fontWeight: '600', marginBottom: '8px' }}>{value}</div>
    <div style={{ fontSize: '12px', color: '#4caf50' }}>{change}</div>
  </div>
);

const ChartContainer = ({ title, children }: { title: string; children: React.ReactNode }) => (
  <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '8px', border: '1px solid #e0e0e0' }}>
    <h3 style={{ margin: '0 0 16px', fontSize: '14px', fontWeight: '600' }}>{title}</h3>
    {children}
  </div>
);

export default AnalyticsDashboard;
```

