// auth.service.ts
import jwt from 'jsonwebtoken';
import axios from 'axios';
import { Redis } from 'ioredis';
import { User } from './user.model';

const redis = new Redis();
const JWT_SECRET = process.env.JWT_SECRET!;
const GOOGLE_CLIENT_ID = process.env.GOOGLE_CLIENT_ID!;
const JWT_EXPIRY = '7d';
const RATE_LIMIT_WINDOW = 5 * 60; // 5 minutes
const RATE_LIMIT_MAX = 10;

export class AuthService {
  static async validateGoogleToken(token: string) {
    try {
      const res = await axios.get(`https://www.googleapis.com/oauth2/v3/tokeninfo?id_token=${token}`);
      if (res.data.aud !== GOOGLE_CLIENT_ID) throw new Error('Invalid audience');
      return res.data;
    } catch (err) {
      throw new Error('Invalid Google token');
    }
  }

  static async checkRateLimit(ip: string) {
    const key = `auth:${ip}`;
    const count = await redis.incr(key);
    if (count === 1) await redis.expire(key, RATE_LIMIT_WINDOW);
    if (count > RATE_LIMIT_MAX) throw new Error('Too many auth attempts');
  }

  static async login(googleData: any) {
    const { email, name, picture } = googleData;

    // Find or create user
    let user = await User.findOne({ email });
    if (!user) {
      user = await User.create({ email, name, picture, googleId: googleData.sub });
    }

    // Generate JWT
    const token = jwt.sign(
      { userId: user.id, email: user.email },
      JWT_SECRET,
      { expiresIn: JWT_EXPIRY }
    );

    // Log successful login
    console.log(`[AUTH] Login successful: ${email}`);

    return { token, user };
  }

  static verifyToken(token: string) {
    try {
      return jwt.verify(token, JWT_SECRET);
    } catch (err) {
      throw new Error('Invalid or expired token');
    }
  }

  static async refreshToken(token: string) {
    const decoded = this.verifyToken(token);
    const newToken = jwt.sign(
      { userId: decoded.userId, email: decoded.email },
      JWT_SECRET,
      { expiresIn: JWT_EXPIRY }
    );
    return newToken;
  }
}

// middleware.ts
import { Request, Response, NextFunction } from 'express';
import { AuthService } from './auth.service';

export const authMiddleware = (req: Request, res: Response, next: NextFunction) => {
  const token = req.cookies.jwt;
  if (!token) return res.status(401).json({ error: 'No token provided' });

  try {
    const decoded = AuthService.verifyToken(token);
    (req as any).userId = decoded.userId;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Unauthorized' });
  }
};

// routes.ts
import express from 'express';
import { AuthService } from './auth.service';
import { authMiddleware } from './middleware';

const router = express.Router();

router.post('/auth/google', async (req, res) => {
  try {
    const ip = req.ip!;
    await AuthService.checkRateLimit(ip);

    const googleData = await AuthService.validateGoogleToken(req.body.token);
    const { token, user } = await AuthService.login(googleData);

    res.cookie('jwt', token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000
    });

    res.json({ user });
  } catch (err: any) {
    console.error(`[AUTH_ERROR] ${err.message}`);
    res.status(400).json({ error: 'Authentication failed' });
  }
});

router.post('/auth/refresh', authMiddleware, async (req, res) => {
  try {
    const oldToken = req.cookies.jwt;
    const newToken = await AuthService.refreshToken(oldToken);

    res.cookie('jwt', newToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000
    });

    res.json({ success: true });
  } catch (err) {
    res.status(401).json({ error: 'Refresh failed' });
  }
});

router.get('/profile', authMiddleware, async (req, res) => {
  const user = await User.findById((req as any).userId);
  res.json(user);
});

export default router;

// auth.test.ts
import { AuthService } from './auth.service';
import request from 'supertest';
import app from './app';

describe('AuthService', () => {
  it('should validate Google token', async () => {
    const token = 'valid-google-token';
    const result = await AuthService.validateGoogleToken(token);
    expect(result).toBeDefined();
  });

  it('should rate limit after 10 attempts', async () => {
    const ip = '127.0.0.1';
    for (let i = 0; i < 10; i++) {
      await AuthService.checkRateLimit(ip);
    }
    expect(() => AuthService.checkRateLimit(ip)).rejects.toThrow('Too many');
  });

  it('should create JWT on login', async () => {
    const googleData = { email: 'test@example.com', name: 'Test', picture: '', sub: '123' };
    const { token } = await AuthService.login(googleData);
    const decoded = AuthService.verifyToken(token);
    expect(decoded.email).toBe('test@example.com');
  });

  it('should reject expired token', async () => {
    const expiredToken = jwt.sign({ userId: '1' }, JWT_SECRET, { expiresIn: '-1s' });
    expect(() => AuthService.verifyToken(expiredToken)).toThrow();
  });
});

describe('Auth Routes', () => {
  it('POST /auth/google should set httpOnly cookie', async () => {
    const res = await request(app)
      .post('/auth/google')
      .send({ token: 'valid-token' });
    expect(res.status).toBe(200);
    expect(res.headers['set-cookie']).toBeDefined();
  });

  it('GET /profile requires auth', async () => {
    const res = await request(app).get('/profile');
    expect(res.status).toBe(401);
  });
});
