it('should reset rate limit counter after window expires', async () => {
  jest.useFakeTimers();
  const ip = '127.0.0.1-test';

  // Hit 10 times
  for (let i = 0; i < 10; i++) {
    await AuthService.checkRateLimit(ip);
  }

  // 11th should fail
  await expect(AuthService.checkRateLimit(ip)).rejects.toThrow('Too many');

  // Fast-forward 5 minutes
  jest.advanceTimersByTime(5 * 60 * 1000 + 1000);

  // Should succeed again (counter reset)
  await expect(AuthService.checkRateLimit(ip)).resolves.not.toThrow();

  jest.useRealTimers();
});
